import{_ as s,o as a,c as i,an as t,j as o,a as n}from"./chunks/framework.CnqFmpaX.js";const f=JSON.parse('{"title":"Contributors Guide","description":"","frontmatter":{},"headers":[],"relativePath":"developer_docs/contributing.md","filePath":"developer_docs/contributing.md","lastUpdated":null}'),r={name:"developer_docs/contributing.md"},l={class:"MathJax",jax:"SVG",overflow:"linebreak"},u={style:{"vertical-align":"-0.025ex"},xmlns:"http://www.w3.org/2000/svg",width:"5.321ex",height:"1.52ex",role:"img",focusable:"false",viewBox:"0 -661 2352 672"};function c(p,e,h,d,g,m){return a(),i("div",null,[e[3]||(e[3]=t('<h1 id="Contributors-Guide" tabindex="-1">Contributors Guide <a class="header-anchor" href="#Contributors-Guide" aria-label="Permalink to &quot;Contributors Guide {#Contributors-Guide}&quot;">​</a></h1><p>Thank you for considering contributions to Oceananigans! We hope this guide helps you make a contribution.</p><p>Feel free to ask us questions and chat with us at any time about any topic at all by:</p><ul><li><p><a href="https://github.com/CliMA/Oceananigans.jl/issues/new" target="_blank" rel="noreferrer">Opening a GitHub issue</a></p></li><li><p><a href="https://github.com/CliMA/Oceananigans.jl/discussions/new" target="_blank" rel="noreferrer">Creating a GitHub discussion</a></p></li><li><p>Sending a message to the <a href="https://julialang.slack.com/archives/C01D24C0CAH" target="_blank" rel="noreferrer">#oceananigans channel</a> on <a href="https://julialang.org/slack/" target="_blank" rel="noreferrer">Julia Slack</a>.</p></li></ul><h2 id="Creating-issues" tabindex="-1">Creating issues <a class="header-anchor" href="#Creating-issues" aria-label="Permalink to &quot;Creating issues {#Creating-issues}&quot;">​</a></h2><p>The simplest way to contribute to Oceananigans is to create or comment on issues and discussions.</p><p>The most useful bug reports:</p><ul><li><p>Provide an explicit code snippet – not just a link – that reproduces the bug in the latest tagged version of Oceananigans. This is sometimes called the <a href="https://en.wikipedia.org/wiki/Minimal_working_example" target="_blank" rel="noreferrer">&quot;minimal working example&quot;</a>. Reducing bug-producing code to a minimal example can dramatically decrease the time it takes to resolve an issue.</p></li><li><p>Paste the <em>entire</em> error received when running the code snippet, even if it&#39;s unbelievably long.</p></li><li><p>Use triple backticks (e.g., <code>some_code; and_some_more_code;</code>) to enclose code snippets, and other <a href="https://docs.github.com/en/get-started/writing-on-github/getting-started-with-writing-and-formatting-on-github/basic-writing-and-formatting-syntax" target="_blank" rel="noreferrer">markdown formatting syntax</a> to make your issue easy and quick to read.</p></li><li><p>Report the Oceananigans version, Julia version, machine (especially if using a GPU) and any other possibly useful details of the computational environment in which the bug was created.</p></li></ul><p>Discussions are recommended for asking questions about (for example) the user interface, implementation details, science, and life in general.</p><h2 id="But-I-want-to-code!" tabindex="-1">But I want to <em>code</em>! <a class="header-anchor" href="#But-I-want-to-code!" aria-label="Permalink to &quot;But I want to _code_! {#But-I-want-to-code!}&quot;">​</a></h2><ul><li><p>New users help write Oceananigans code and documentation by <a href="https://docs.github.com/en/pull-requests/collaborating-with-pull-requests/working-with-forks" target="_blank" rel="noreferrer">forking the Oceananigans repository</a>, <a href="https://docs.github.com/get-started/using-git/about-git" target="_blank" rel="noreferrer">using git</a> to edit code and docs, and then creating a <a href="https://docs.github.com/en/pull-requests/collaborating-with-pull-requests/proposing-changes-to-your-work-with-pull-requests/creating-a-pull-request-from-a-fork" target="_blank" rel="noreferrer">pull request</a>. Pull requests are reviewed by Oceananigans collaborators.</p></li><li><p>A pull request can be merged once it is reviewed and approved by collaborators. If the pull request author has write access, they have the responsibility of merging their pull request. Otherwise, Oceananigans.jl collaborators will execute the merge with permission from the pull request author.</p></li><li><p>Note: for small or minor changes (such as fixing a typo in documentation), the <a href="https://docs.github.com/en/repositories/working-with-files/managing-files/editing-files" target="_blank" rel="noreferrer">GitHub editor</a> is super useful for forking and opening a pull request with a single click.</p></li><li><p>Write your code with love and care. In particular, conform to existing Oceananigans style and formatting conventions. For example, we love verbose and explicit variable names, use <code>TitleCase</code> for types, <code>snake_case</code> for objects, and always,put,spaces.after.commas,or.periods. For formatting decisions we loosely follow the <a href="https://github.com/jrevels/YASGuide" target="_blank" rel="noreferrer">YASGuide</a>. It&#39;s worth few extra minutes of our time to leave future generations with well-written, readable code.</p></li></ul><h2 id="What-is-a-&quot;collaborator&quot;-and-how-can-I-become-one?" tabindex="-1">What is a &quot;collaborator&quot; and how can I become one? <a class="header-anchor" href="#What-is-a-&quot;collaborator&quot;-and-how-can-I-become-one?" aria-label="Permalink to &quot;What is a &quot;collaborator&quot; and how can I become one? {#What-is-a-&quot;collaborator&quot;-and-how-can-I-become-one?}&quot;">​</a></h2><ul><li><p>Collaborators have permissions to review pull requests and status allows a contributor to review pull requests in addition to opening them. Collaborators can also create branches in the main Oceananigans repository.</p></li><li><p>We ask that new contributors try their hand at forking Oceananigans, and opening and merging a pull request before requesting collaborator status.</p></li></ul><h2 id="What&#39;s-a-good-way-to-start-developing-Oceananigans?" tabindex="-1">What&#39;s a good way to start developing Oceananigans? <a class="header-anchor" href="#What&#39;s-a-good-way-to-start-developing-Oceananigans?" aria-label="Permalink to &quot;What&#39;s a good way to start developing Oceananigans? {#What&#39;s-a-good-way-to-start-developing-Oceananigans?}&quot;">​</a></h2><ul><li><p>Tackle an existing issue. We keep a list of <a href="https://github.com/CLiMA/Oceananigans.jl/issues?q=is%3Aissue+is%3Aopen+label%3A%22good+first+issue%22" target="_blank" rel="noreferrer">good first issues</a> that are self-contained and suitable for a newcomer to try and work on.</p></li><li><p>Try to run Oceananigans and play around with it to simulate your favorite fluids and ocean physics. If you run into any problems or find it difficult to use or understand, please open an issue!</p></li><li><p>Write up an example or tutorial on how to do something useful with Oceananigans, like how to set up a new physical configuration.</p></li><li><p>Improve documentation or comments if you found something hard to use.</p></li><li><p>Implement a new feature if you need it to use Oceananigans.</p></li></ul><p>If you&#39;re interested in working on something, let us know by commenting on existing issues or by opening a new issue. This is to make sure no one else is working on the same issue and so we can help and guide you in case there is anything you need to know beforehand.</p><h2 id="Ground-Rules" tabindex="-1">Ground Rules <a class="header-anchor" href="#Ground-Rules" aria-label="Permalink to &quot;Ground Rules {#Ground-Rules}&quot;">​</a></h2><ul><li><p>Each pull request should consist of a logical collection of changes. You can include multiple bug fixes in a single pull request, but they should be related. For unrelated changes, please submit multiple pull requests.</p></li><li><p>Do not commit changes to files that are irrelevant to your feature or bugfix (eg: <code>.gitignore</code>).</p></li><li><p>Be willing to accept criticism and work on improving your code; we don&#39;t want to break other users&#39; code, so care must be taken not to introduce bugs. We discuss pull requests and keep working on them until we believe we&#39;ve done a good job.</p></li><li><p>Be aware that the pull request review process is not immediate, and is generally proportional to the size of the pull request.</p></li></ul><h2 id="Reporting-a-bug" tabindex="-1">Reporting a bug <a class="header-anchor" href="#Reporting-a-bug" aria-label="Permalink to &quot;Reporting a bug {#Reporting-a-bug}&quot;">​</a></h2><p>The easiest way to get involved is to report issues you encounter when using Oceananigans or by requesting something you think is missing.</p><ul><li><p>Head over to the <a href="https://github.com/CLiMA/Oceananigans.jl/issues" target="_blank" rel="noreferrer">issues</a> page.</p></li><li><p>Search to see if your issue already exists or has even been solved previously.</p></li><li><p>If you indeed have a new issue or request, click the &quot;New Issue&quot; button.</p></li><li><p>Please be as specific as possible. Include the version of the code you were using, as well as what operating system you are running. The output of Julia&#39;s <code>versioninfo()</code> and <code>] status</code> is helpful to include. Try your best to include a complete, <a href="https://en.wikipedia.org/wiki/Minimal_working_example" target="_blank" rel="noreferrer">&quot;minimal working example&quot;</a> that reproduces the issue.</p></li></ul><h2 id="Setting-up-your-development-environment" tabindex="-1">Setting up your development environment <a class="header-anchor" href="#Setting-up-your-development-environment" aria-label="Permalink to &quot;Setting up your development environment {#Setting-up-your-development-environment}&quot;">​</a></h2><ul><li><p>Install <a href="https://julialang.org/" target="_blank" rel="noreferrer">Julia</a> on your system.</p></li><li><p>Install <code>git</code> on your system if it is not already there (install XCode command line tools on a Mac or <code>git bash</code> on Windows).</p></li><li><p>Login to your GitHub account and make a fork of the <a href="https://github.com/CLiMA/Oceananigans.jl" target="_blank" rel="noreferrer">Oceananigans repository</a> by clicking the &quot;Fork&quot; button.</p></li><li><p>Clone your fork of the Oceananigans repository (in terminal on Mac/Linux or git shell/ GUI on Windows) in the location you&#39;d like to keep it.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git clone https://github.com/your-user-name/Oceananigans.jl.git</span></span></code></pre></div></li><li><p>Navigate to that folder in the terminal or in Anaconda Prompt if you&#39;re on Windows.</p></li><li><p>Connect your repository to the upstream (main project).</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git remote add oceananigans https://github.com/CLiMA/Oceananigans.jl.git</span></span></code></pre></div></li><li><p>Create the development environment by opening Julia via <code>julia --project</code> then typing in <code>] instantiate</code>. This will install all the dependencies in the Project.toml file. Your development environment is now ready!</p></li><li><p>You can test to make sure Oceananigans works by typing in <code>] test</code>. (This is equivalent to <code>using Pkg; Pkg.test()</code>.) Doing so will run all the tests (and this can take a while). Alternatively, we can run only one test script file by providing its name as an environment variable. For example, to run the tests only from the <code>test_coriolis.jl</code> file we call:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> TEST_FILE=test_coriolis.jl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;using Pkg; Pkg.test()&quot;</span></span></code></pre></div><p>We can also run all the tests within a certain test group, as they are defined in <a href="https://github.com/CliMA/Oceananigans.jl/blob/main/test/runtests.jl" target="_blank" rel="noreferrer"><code>test/runtest.jl</code></a>. For example, to run all unit tests we call:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> TEST_GROUP=unit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;using Pkg; Pkg.test()&quot;</span></span></code></pre></div></li></ul><h2 id="Pull-Requests" tabindex="-1">Pull Requests <a class="header-anchor" href="#Pull-Requests" aria-label="Permalink to &quot;Pull Requests {#Pull-Requests}&quot;">​</a></h2><p>We follow the <a href="https://github.com/SciML/ColPrac" target="_blank" rel="noreferrer">ColPrac guide</a> for collaborative practices. We ask that new contributors read that guide before submitting a pull request.</p>',25)),o("p",null,[e[1]||(e[1]=n("Changes and contributions should be made via GitHub pull requests against the ",-1)),o("mjx-container",l,[(a(),i("svg",u,[...e[0]||(e[0]=[t('<g stroke="currentColor" fill="currentColor" stroke-width="0" transform="scale(1,-1)"><g data-mml-node="math" data-latex="main"><g data-mml-node="mi" data-latex="m"><path data-c="1D45A" d="M657 442C596 442 543 412 498 353C489 412 451 442 383 442C324 442 273 416 231 363C223 407 188 442 137 442C96 442 66 409 45 344C34 312 29 293 29 287C29 278 34 273 45 273C50 273 53 274 56 276C61 285 64 292 66 299C84 375 107 413 134 413C152 413 161 399 161 371C161 358 156 331 145 290L88 63C84 51 79 25 79 19C79-1 90-11 111-11C131-11 145-1 152 19C153 24 160 49 171 92L192 181L222 295C233 318 250 341 272 365C301 397 337 413 380 413C413 413 429 391 429 348C429 335 424 308 414 267L387 153C380 124 364 64 356 32C355 25 354 21 354 19C354-1 365-11 387-11C398-11 406-8 413-1C428 14 429 21 435 48L494 285C497 298 511 321 535 353C565 393 605 413 654 413C687 413 703 391 703 348C703 309 683 236 642 129C633 106 629 87 629 74C629 25 666-11 714-11C759-11 793 14 818 64C838 104 848 131 848 144C848 153 843 158 832 158C825 157 818 148 813 137C791 58 759 18 716 18C703 18 696 28 696 47C696 62 702 84 714 115C755 222 775 295 775 333C775 404 728 442 657 442Z"></path></g><g data-mml-node="mi" data-latex="a" transform="translate(878,0)"><path data-c="1D44E" d="M498 144C498 153 493 158 482 158C474 158 468 151 465 137C445 58 421 18 394 18C377 18 368 32 368 60C368 73 372 97 381 132L438 357C443 376 445 387 445 392C445 412 434 422 412 422C391 422 377 410 370 387C349 424 319 442 281 442C216 442 159 409 109 343C63 281 40 217 40 150C40 63 91-11 175-11C218-11 260 12 300 58C311 20 345-11 392-11C461-11 482 70 498 144M341 374C350 353 355 339 355 330C355 326 354 321 353 314L304 122C301 111 294 99 285 87C248 41 212 18 177 18C138 18 118 48 118 107C118 131 124 167 136 215C157 300 187 357 224 388C244 405 263 413 282 413C309 413 329 400 341 374Z"></path></g><g data-mml-node="mi" data-latex="i" transform="translate(1407,0)"><path data-c="1D456" d="M284 621C284 648 271 661 244 661C216 661 188 633 188 605C188 578 202 565 229 565C257 565 284 593 284 621M259 138C237 59 205 19 164 19C151 19 144 28 144 47C144 64 173 150 232 306C240 329 244 347 244 360C244 409 210 445 161 445C118 445 84 420 59 369C39 328 29 301 29 288C29 279 34 275 45 275C58 275 60 281 64 295C87 375 118 415 158 415C171 415 178 406 178 387C178 373 175 357 168 338C145 275 121 208 101 155C86 115 78 88 78 74C78 25 114-11 162-11C205-11 239 14 264 64C283 103 293 130 293 145C293 154 288 159 277 159C274 159 259 150 259 138Z"></path></g><g data-mml-node="mi" data-latex="n" transform="translate(1752,0)"><path data-c="1D45B" d="M537 137C514 58 481 18 440 18C427 18 420 28 420 47C420 61 426 84 438 115C478 224 498 296 498 333C498 403 451 442 381 442C322 442 271 416 230 363C222 407 187 442 136 442C80 442 58 390 44 345C34 313 29 294 29 287C29 278 34 273 45 273C50 273 53 274 56 276C61 285 64 292 65 299C83 375 106 413 133 413C151 413 160 399 160 371C160 358 155 331 144 290L87 63C84 50 78 24 78 19C78-1 89-11 111-11C130-11 144-1 151 19C153 24 159 49 170 92L191 181L221 295C232 318 249 341 270 365C299 397 335 413 378 413C411 413 427 391 427 348C427 310 406 234 363 120C356 102 353 87 353 74C353 25 390-11 438-11C482-11 517 14 542 64C561 104 571 131 571 144C571 153 566 158 555 158C552 158 537 149 537 137Z"></path></g></g></g>',1)])]))]),e[2]||(e[2]=n(" branch.",-1))]),e[4]||(e[4]=t('<p>When you&#39;re done making changes, commit the changes you made. Chris Beams has written a <a href="https://chris.beams.io/git-commit" target="_blank" rel="noreferrer">guide</a> on how to write good commit messages.</p><p>When you think your changes are ready to be merged into the main repository, push to your fork and <a href="https://github.com/CLiMA/Oceananigans.jl/compare/" target="_blank" rel="noreferrer">submit a pull request</a>.</p><p><strong>Working on your first Pull Request?</strong> You can learn how from this <em>free</em> video series <a href="https://egghead.io/courses/how-to-contribute-to-an-open-source-project-on-github" target="_blank" rel="noreferrer">How to Contribute to an Open Source Project on GitHub</a>, Aaron Meurer&#39;s <a href="https://www.asmeurer.com/git-workflow/" target="_blank" rel="noreferrer">tutorial on the git workflow</a>, or the guide <a href="https://opensource.guide/how-to-contribute/" target="_blank" rel="noreferrer">“How to Contribute to Open Source&quot;</a>.</p><h2 id="Documentation" tabindex="-1">Documentation <a class="header-anchor" href="#Documentation" aria-label="Permalink to &quot;Documentation {#Documentation}&quot;">​</a></h2><p>Now that you&#39;ve made your awesome contribution, it&#39;s time to tell the world how to use it. Writing documentation strings is really important to make sure others use your functionality properly. Didn&#39;t write new functions? That&#39;s fine, but be sure that the documentation for the code you touched is still in great shape. It is not uncommon to find some strange wording or clarification that you can take care of while you are here.</p><p>You can preview how the Documentation will look like after merging by building the documentation locally. From the main directory of your local repository call</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>julia --project=docs/ -e &#39;using Pkg; Pkg.develop(PackageSpec(path=pwd())); Pkg.instantiate()&#39;</span></span></code></pre></div><p>to instantiate the documentation environment and then</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>JULIA_DEBUG=Documenter julia --project=docs/ docs/make.jl</span></span></code></pre></div><p>If the documentation built is successful, you can open <code>docs/build/index.html</code> in your favorite browser.Providing the environment variable <code>JULIA_DEBUG=Documenter</code> will provide with more information in the documentation build process and thus help figuring out a potential bug.</p><h2 id="Pre-commit-hook" tabindex="-1">Pre-commit hook <a class="header-anchor" href="#Pre-commit-hook" aria-label="Permalink to &quot;Pre-commit hook {#Pre-commit-hook}&quot;">​</a></h2><p>This project uses <a href="https://pre-commit.com/" target="_blank" rel="noreferrer">pre-commit</a> for ensuring some minimal formatting consistency in the codebase, in particular related to whitespace.</p><h3 id="Installing-a-pre-commit-manager" tabindex="-1">Installing a pre-commit manager <a class="header-anchor" href="#Installing-a-pre-commit-manager" aria-label="Permalink to &quot;Installing a pre-commit manager {#Installing-a-pre-commit-manager}&quot;">​</a></h3><p>You can install a &quot;pre-commit manager&quot; locally so that you can automatically ensure to adapt to the project style. There are multiple pre-commit managers you can install, some alternatives are:</p><ul><li><p>the original <a href="https://pre-commit.com/" target="_blank" rel="noreferrer">pre-commit</a>: follow the <a href="https://pre-commit.com/#install" target="_blank" rel="noreferrer">instructions to install it</a>, and then move in the terminal inside the Oceananigans repository and run the command</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pre-commit install</span></span></code></pre></div><p>to install the hooks</p></li><li><p>a new (and faster) manager called <a href="https://prek.j178.dev/" target="_blank" rel="noreferrer">prek</a>: follow the <a href="https://prek.j178.dev/installation/" target="_blank" rel="noreferrer">instructions to install it</a>, and then move in the terminal inside the Oceananigans repository and run the command</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>prek install</span></span></code></pre></div><p>to install the hooks.</p></li></ul><p>That&#39;s it! After you install the pre-commit manager and the hooks for this repository, you don&#39;t have to do anything else manually: whenever you run <code>git commit</code> in this repository, the manager will automatically run the hooks and fix the possible issues.</p><div class="tip custom-block"><p class="custom-block-title">Note</p><p>If a pre-commit hooks detects an issue and automatically fixes it, the git commit actually fails. In that case you will have to <code>git add</code> the new changes and <code>git commit</code> again to make the commit successful.</p></div><h2 id="Credits" tabindex="-1">Credits <a class="header-anchor" href="#Credits" aria-label="Permalink to &quot;Credits {#Credits}&quot;">​</a></h2><p>This contributor&#39;s guide is heavily based on the excellent <a href="https://github.com/Unidata/MetPy/blob/master/CONTRIBUTING.md" target="_blank" rel="noreferrer">MetPy contributor&#39;s guide</a>.</p>',19))])}const k=s(r,[["render",c]]);export{f as __pageData,k as default};
